    /** (container, onContainer) for a course; stable per course id. Unknown preset falls back to slate. */
    fun course(preset: String, courseId: Long, dark: Boolean): Pair<Color, Color> {
        val set = (if (dark) courseDark else courseLight).let { it[preset] ?: it.getValue("slate") }
        return set[Math.floorMod(courseId, set.size.toLong()).toInt()]
    }
